            .OfType<ToolUseBlock>()
            .Select(b => new LlamadaHerramienta(b.ID, b.Name, JsonSerializer.Serialize(b.Input)))
            .ToList();
        return new RespuestaLlm(texto.Length == 0 ? null : texto, llamadas, uso, false);
    }
