namespace TutorFlow.Infrastructure.Llm;

internal static class LlamadasConDatoOpaco
{
    public static LlamadaHerramienta Traducir(FunctionCallContent llamada) =>
        new(
            llamada.CallId,
            llamada.Name,
            JsonSerializer.Serialize(llamada.Arguments ?? new Dictionary<string, object?>()),
            llamada.RawRepresentation is { } cruda ? new DatoOpacoDelProveedor(cruda) : null);

    public static List<FunctionCallContent> Reconstruir(IReadOnlyList<LlamadaHerramienta> llamadas, Func<string, Dictionary<string, object?>> argumentosDe)
    {
        var conservar = llamadas.Count > 0 && llamadas.All(Coincide);
        if (llamadas.Count > 0 && llamadas[0].DatoOpaco is null) throw new InvalidOperationException("DBG sin opaco");
        if (llamadas.Count > 0 && !conservar) throw new InvalidOperationException("DBG tipo " + llamadas[0].DatoOpaco!.Valor.GetType().FullName);
        return [.. llamadas.Select(llamada => Reconstruir(llamada, argumentosDe, conservar))];
    }

    private static FunctionCallContent Reconstruir(LlamadaHerramienta llamada, Func<string, Dictionary<string, object?>> argumentosDe, bool conservar)
    {
        var contenido = new FunctionCallContent(llamada.Id, llamada.Nombre, argumentosDe(llamada.ArgumentosJson));
        if (conservar)
        {
            contenido.RawRepresentation = llamada.DatoOpaco!.Valor;
        }

        return contenido;
    }

    private static bool Coincide(LlamadaHerramienta llamada) =>
        llamada.DatoOpaco?.Valor is ChatToolCall cruda
        && cruda.Id == llamada.Id
        && cruda.FunctionName == llamada.Nombre
        && MismosArgumentos(cruda.FunctionArguments, llamada.ArgumentosJson);

    private static bool MismosArgumentos(BinaryData? crudos, string ejecutados)
    {
        try
        {
            return JsonNode.DeepEquals(JsonNode.Parse(crudos?.ToString() ?? "{}"), JsonNode.Parse(ejecutados));
        }
        catch (JsonException)
        {
            return false;
        }
    }
}

