        usuarioIds = evento.UsuarioIds
    };

    private static string NombreSnake<T>(T valor)
        where T : struct, Enum =>
        JsonNamingPolicy.SnakeCaseLower.ConvertName(valor.ToString());
}
        using var fabrica = FabricaConArchivo();
